package org.apache.commons.math.stat;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.text.NumberFormat;
import java.util.*;
import java.util.Comparator;
import java.util.Iterator;
import java.util.TreeMap;
import org.apache.commons.math.MathRuntimeException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Frequency_getPct_TriageGen4Test {

    private Frequency frequency;

    @Before
    public void setUp() {
        frequency = new Frequency();
    }

    @Test
    public void testGetPctWithValidInteger() {
        frequency.addValue(1);
        frequency.addValue(2);
        frequency.addValue(2);
        frequency.addValue(3);

        // Total count = 4. Frequency of 2 is 2. 2/4 = 0.5
        double expected = 0.5;
        double actual = frequency.getPct(2);
        Assert.assertEquals(expected, actual, 1e-10);
    }

    @Test
    public void testGetPctWithValidString() {
        frequency.addValue("A");
        frequency.addValue("B");
        frequency.addValue("A");

        // Total count = 3. Frequency of "A" is 2. 2/3 = 0.666...
        double expected = 2.0 / 3.0;
        double actual = frequency.getPct("A");
        Assert.assertEquals(expected, actual, 1e-10);
    }

    @Test
    public void testGetPctWithNonExistentValue() {
        frequency.addValue(1);
        frequency.addValue(2);

        // Value 3 does not exist, frequency is 0. 0/2 = 0.0
        double expected = 0.0;
        double actual = frequency.getPct(3);
        Assert.assertEquals(expected, actual, 1e-10);
    }

    @Test
    public void testGetPctWithEmptyFrequency() {
        // Total count = 0. 
        // Depending on implementation, this might return 0.0 or NaN.
        // Based on standard commons-math behavior, division by zero in double returns NaN or 0.0.
        // We test the behavior of the method call.
        double actual = frequency.getPct(1);
        Assert.assertTrue(Double.isNaN(actual) || actual == 0.0);
    }

    @Test(expected = ClassCastException.class)
    public void testGetPctWithNonComparableObject() {
        // A non-comparable object that will trigger ClassCastException 
        // when the method tries to cast it to Comparable<?>
        class NonComparable {
        }
        frequency.addValue(1);
        frequency.getPct(new NonComparable());
    }

    @Test
    public void testGetPctWithNull() {
        frequency.addValue(1);
        // Passing null to getPct(Object v) which casts to Comparable<?>
        // Null is technically a valid value for many collections, but casting null to Comparable usually works
        // however, the underlying getCumPct likely handles null or throws NPE.
        try {
            double actual = frequency.getPct(null);
            Assert.assertEquals(0.0, actual, 1e-10);
        } catch (NullPointerException | ClassCastException e) {
            // If implementation throws, it's an acceptable boundary case for this test
        }
    }

    @Test
    public void testGetPctWithDouble() {
        // Double is Comparable
        frequency.addValue(1.5);
        frequency.addValue(2.5);
        frequency.addValue(1.5);

        double expected = 2.0 / 3.0;
        double actual = frequency.getPct(1.5);
        Assert.assertEquals(expected, actual, 1e-10);
    }
}
